DROP VIEW IF EXISTS tmp_v_compras;
DROP TABLE IF EXISTS tmp_csv_compras;
DROP TABLE IF EXISTS tmp_csv_compras_web;
CREATE EXTERNAL TABLE tmp_csv_compras (id_compra string, fecha string, proveedor_id string, producto_id string, categoria_id string, unidad_organizacional_id string, cantidad string, precio_unitario string, moneda string, condicion_pago string, lead_time_dias string) PARTITIONED BY (anio string, mes string) ROW FORMAT SERDE 'org.apache.hadoop.hive.serde2.OpenCSVSerde' LOCATION 's3://<bucket-maghsa-dwh>/raw/compras/' TBLPROPERTIES ('skip.header.line.count'='1');
MSCK REPAIR TABLE tmp_csv_compras;
CREATE EXTERNAL TABLE tmp_csv_compras_web (id_compra string, fecha string, proveedor_id string, producto_id string, categoria_id string, unidad_organizacional_id string, cantidad string, precio_unitario string, moneda string, condicion_pago string, lead_time_dias string) ROW FORMAT SERDE 'org.apache.hadoop.hive.serde2.OpenCSVSerde' LOCATION 's3://<bucket-maghsa-dwh>/raw/compras_web/' TBLPROPERTIES ('skip.header.line.count'='1');
-- anio/mes del web salen de fecha (yyyy-MM-dd); fechas posteriores a hoy no entran
CREATE OR REPLACE VIEW tmp_v_compras AS SELECT id_compra, fecha, proveedor_id, producto_id, categoria_id, unidad_organizacional_id, cantidad, precio_unitario, moneda, condicion_pago, lead_time_dias, anio, mes FROM tmp_csv_compras WHERE CAST(fecha AS date) <= CAST(current_timestamp AT TIME ZONE 'America/Guatemala' AS date) UNION ALL SELECT id_compra, fecha, proveedor_id, producto_id, categoria_id, unidad_organizacional_id, cantidad, precio_unitario, moneda, condicion_pago, lead_time_dias, substr(fecha, 1, 4) AS anio, substr(fecha, 6, 2) AS mes FROM tmp_csv_compras_web WHERE CAST(fecha AS date) <= CAST(current_timestamp AT TIME ZONE 'America/Guatemala' AS date);
